input.command:
awk '
/^\/--$/ && !done {hold=1}
{ if (hold) buf = buf $0 "\n"; else print }
' putnam_2006_b6.lean > /dev/null; 
start=$(grep -n '^/--$' putnam_2006_b6.lean | head -1 | cut -d: -f1); lem=$(grep -n '^lemma key_bound' putnam_2006_b6.lean | cut -d: -f1); thm=$(grep -n '^theorem putnam_2006_b6' putnam_2006_b6.lean | cut -d: -f1);
{ sed -n "1,$((start-1))p" putnam_2006_b6.lean; sed -n "${lem},$((thm-2))p" putnam_2006_b6.lean; sed -n "${start},$((lem-1))p" putnam_2006_b6.lean; sed -n "$((thm-1)),\$p" putnam_2006_b6.lean; } > /tmp/new.lean && mv /tmp/new.lean putnam_2006_b6.lean && sed -n 1,12p putnam_2006_b6.lean && grep -n "sorry\|axiom\|native" putnam_2006_b6.lean; lean putnam_2006_b6.lean; echo EXIT $?
